class Resource:
    def __init__(self, resource_id: str, amount: int):
        self.id = resource_id
        self.amount = amount

class Component:
    def __init__(self, component_id: str, blueprint: Dict[str, Any]):
        self.id = component_id
        self.resources_needed = blueprint["resources"].copy()
        self.craft_time = blueprint["craft_time"]
        self.current_craft_time = 0
        self.ready_for_assembly = False

    def add_craft_time(self, amount: int):
        if not self.ready_for_assembly:
            self.current_craft_time += amount
            if self.current_craft_time >= self.craft_time:
                self.ready_for_assembly = True

class BuildingComponent:
    def __init__(self, component_id: str, dependencies: List[str]):
        self.id = component_id
        self.dependencies = dependencies
        self.crafted_ready = False 
        self.assembled = False

    def check_crafted_ready(self, world_components: Dict[str, Component]):
        base_comp_id = '_'.join(self.id.split('_')[:-1])
        if base_comp_id in world_components and world_components[base_comp_id].ready_for_assembly:
            self.crafted_ready = True

    def check_dependencies(self, global_assembled_status: Dict[str, bool]) -> bool:
        return all(global_assembled_status.get(dep, False) for dep in self.dependencies)

    def assemble(self):
        if self.crafted_ready and not self.assembled:
            self.assembled = True

